package platform

import jetbrains.buildServer.configs.kotlin.*
import jetbrains.buildServer.configs.kotlin.buildFeatures.commitStatusPublisher
import jetbrains.buildServer.configs.kotlin.buildFeatures.pullRequests
import jetbrains.buildServer.configs.kotlin.triggers.finishBuildTrigger
import jetbrains.buildServer.configs.kotlin.triggers.vcs
import jetbrains.buildServer.configs.kotlin.vcs.GitVcsRoot
import java.io.File

/*
 * Generates one application in the build-once / deploy-many layout:
 *
 *   <BU> / <App>
 *   ├── Build
 *   │   ├── Function Application
 *   │   │   └── <repo>            build every branch + PR, publish app.zip
 *   │   └── Web Application
 *   │       └── <repo>
 *   └── Deploy
 *       ├── DEV                   auto-deploys default-branch builds
 *       │   ├── Deploy all
 *       │   └── Deploy <repo>     artifact dependency on the repo's Build
 *       ├── INT / QA              promote a build that passed DEV
 *       └── PROD                  restrict via TeamCity roles on this project
 *
 * idp = ID prefix. Empty on the server (IDs are relative to the app project);
 * "<AppId>_" when every app is generated side by side for validation.
 */
object AppGenerator {

    fun apply(root: Project, app: AppSpec, baseDir: File, idp: String) {
        val repos = Repos.load(baseDir, app)

        root.description = "Generated by teamcity-platform from Catalog.kt (${repos.size} repos). Do not edit in the UI."
        root.params {
            param("platform.app.key", app.key)
        }

        val buildProject = Project {
            id("${idp}Build")
            name = "Build"
        }
        val deployProject = Project {
            id("${idp}Deploy")
            name = "Deploy"
        }

        val groups = linkedMapOf<String, Project>()
        val builds = linkedMapOf<String, BuildType>()

        repos.forEach { repo ->
            val template = Templates.of(repo.type)
            val group = groups.getOrPut(repo.type) {
                Project {
                    id("${idp}Build_${sanitize(template.group)}")
                    name = template.group
                }
            }
            val vcsRoot = repoVcsRoot(repo, idp)
            group.vcsRoot(vcsRoot)
            val build = buildConfig(repo, vcsRoot, idp)
            group.buildType(build)
            builds[repo.name] = build
        }

        groups.values.forEach { buildProject.subProject(it) }
        app.envs.forEach { env -> deployProject.subProject(envProject(app, env, repos, builds, idp)) }

        root.subProject(buildProject)
        root.subProject(deployProject)
    }

    private fun repoVcsRoot(repo: RepoSpec, idp: String) = GitVcsRoot {
        id("${idp}Repo_${repo.id}")
        name = repo.name
        url = repo.url
        branch = repo.branch
        branchSpec = "+:refs/heads/*"
        authMethod = password {
            userName = "teamcity"
            password = "%ado.pat%"
        }
    }

    private fun buildConfig(repo: RepoSpec, vcsRoot: GitVcsRoot, idp: String) = BuildType {
        id("${idp}Build_${repo.id}")
        name = repo.name
        description = "${repo.type} - build once, deploy many"

        vcs {
            root(vcsRoot)
            cleanCheckout = true
        }

        artifactRules = """
            app.zip
            build-info.txt
        """.trimIndent()

        Templates.buildSteps(this)

        triggers {
            vcs {
                branchFilter = "+:*"
            }
        }

        features {
            pullRequests {
                vcsRootExtId = "${vcsRoot.id}"
                provider = azureDevOps {
                    authType = token {
                        token = "%ado.pat%"
                    }
                    filterTargetBranch = "+:<default>"
                }
            }
            commitStatusPublisher {
                vcsRootExtId = "${vcsRoot.id}"
                publisher = vsts {
                    authType = personalToken {
                        token = "%ado.pat%"
                    }
                }
            }
        }
    }

    private fun envProject(
        app: AppSpec,
        env: EnvSpec,
        repos: List<RepoSpec>,
        builds: Map<String, BuildType>,
        idp: String,
    ): Project {
        val envLower = env.name.lowercase()

        val deploys = repos.map { repo ->
            val build = builds.getValue(repo.name)
            BuildType {
                id("${idp}Deploy_${env.name}_${repo.id}")
                name = "Deploy ${repo.name}"
                type = BuildTypeSettings.Type.DEPLOYMENT
                maxRunningBuilds = 1
                enablePersonalBuilds = false

                params {
                    param("env.AZURE_APP_NAME", "${repo.azureName}-$envLower")
                }

                Templates.deployGuard(this, env)
                Templates.of(repo.type).deploySteps(this, repo)

                dependencies {
                    dependency(build) {
                        snapshot {
                            onDependencyFailure = FailureAction.FAIL_TO_START
                        }
                        artifacts {
                            artifactRules = """
                                app.zip
                                build-info.txt
                            """.trimIndent()
                        }
                    }
                }

                if (env.autoDeploy) {
                    triggers {
                        finishBuildTrigger {
                            buildType = "${build.id}"
                            successfulOnly = true
                            branchFilter = "+:<default>"
                        }
                    }
                }
            }
        }

        return Project {
            id("${idp}Deploy_${env.name}")
            name = env.name
            description = if (env.protected) "Default-branch builds only" else "Any branch may be deployed"

            // Credentials are defined once (as password parameters) on the BU project:
            //   azure.tenant.id, azure.<env>.client.id, azure.<env>.client.secret
            params {
                param("env.TARGET_ENV", env.name)
                param("env.AZURE_RESOURCE_GROUP", app.resourceGroupFor(env))
                param("env.AZURE_TENANT_ID", "%azure.tenant.id%")
                param("env.AZURE_CLIENT_ID", "%azure.$envLower.client.id%")
                param("env.AZURE_CLIENT_SECRET", "%azure.$envLower.client.secret%")
            }

            deploys.forEach { buildType(it) }

            if (deploys.isNotEmpty()) {
                buildType(BuildType {
                    id("${idp}Deploy_${env.name}_All")
                    name = "Deploy all"
                    type = BuildTypeSettings.Type.COMPOSITE
                    dependencies {
                        deploys.forEach { d -> snapshot(d) {} }
                    }
                })
            }
        }
    }
}
